 react-mfe/webpack.config.js: add react/jsx-runtime and scheduler to externals to prevent bundling a second React copy alongside the import-mapped one\n- add root.component.js and react-mfe.js entry point for the React-micro app\n- add .gitignore to stop tracking node_modules and other build artifacts","tree":{"sha":"56d55b96baf9de202746ed17cc165af55e229283","url":"https://api.github.com/repos/Squezer123/Micro-frontends/git/trees/56d55b96baf9de202746ed17cc165af55e229283"},"url":"https://api.github.com/repos/Squezer123/Micro-frontends/git/commits/50c76a278fd26e8c8c99cd3ca30c955e297a267c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/109162813?v=4","events_url":"https://api.github.com/users/Squezer123/events{/privacy}","followers_url":"https://api.github.com/users/Squezer123/followers","following_url":"https://api.github.com/users/Squezer123/following{/other_user}","gists_url":"https://api.github.com/users/Squezer123/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Squezer123","id":109162813,"login":"Squezer123","node_id":"U_kgDOBoGxPQ","organizations_url":"https://api.github.com/users/Squezer123/orgs","received_events_url":"https://api.github.com/users/Squezer123/received_events","repos_url":"https://api.github.com/users/Squezer123/repos","site_admin":false,"starred_url":"https://api.github.com/users/Squezer123/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Squezer123/subscriptions","type":"User","url":"https://api.github.com/users/Squezer123","user_view_type":"public"},"html_url":"https://github.com/Squezer123/Micro-frontends/commit/50c76a278fd26e8c8c99cd3ca30c955e297a267c","node_id":"C_kwDOTtWzZdoAKDUwYzc2YTI3OGZkMjZlOGM4Yzk5Y2QzY2EzMGM5NTVlMjk3YTI2N2M","parents":[{"html_url":"https://github.com/Squezer123/Micro-frontends/commit/b9239cad94ce14d859290fb4b57d6573b0101281","sha":"b9239cad94ce14d859290