rd-level in\npractice.","tree":{"sha":"ce80b6d310a40cdd9b8f1bf6d2c58af01bd2e6ff","url":"https://api.github.com/repos/Vatsa10/Harbour/git/trees/ce80b6d310a40cdd9b8f1bf6d2c58af01bd2e6ff"},"url":"https://api.github.com/repos/Vatsa10/Harbour/git/commits/ad11861c37b9e5b42e91ad770c256977b6395611","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/123623531?v=4","events_url":"https://api.github.com/users/Vatsa10/events{/privacy}","followers_url":"https://api.github.com/users/Vatsa10/followers","following_url":"https://api.github.com/users/Vatsa10/following{/other_user}","gists_url":"https://api.github.com/users/Vatsa10/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Vatsa10","id":123623531,"login":"Vatsa10","node_id":"U_kgDOB15Yaw","organizations_url":"https://api.github.com/users/Vatsa10/orgs","received_events_url":"https://api.github.com/users/Vatsa10/received_events","repos_url":"https://api.github.com/users/Vatsa10/repos","site_admin":false,"starred_url":"https://api.github.com/users/Vatsa10/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Vatsa10/subscriptions","type":"User","url":"https://api.github.com/users/Vatsa10","user_view_type":"public"},"html_url":"https://github.com/Vatsa10/Harbour/commit/ad11861c37b9e5b42e91ad770c256977b6395611","node_id":"C_kwDOTtosW9oAKGFkMTE4NjFjMzdiOWU1YjQyZTkxYWQ3NzBjMjU2OTc3YjYzOTU2MTE","parents":[{"html_url":"https://github.com/Vatsa10/Harbour/commit/34ff5387ff2500fde7b6495a3ffa4a93630e116f","sha":"34ff5387ff2500fde7b6495a3ffa4a93630e116f","url":"https://api.github.com/repos/Vatsa10/Harbour/commits/34ff5387ff2500fde7b6495a3ffa4a93630e116f"}],"sha":"ad11861c37b9e5b42e91ad770c256977b6395611","url":"https://api.github.com/repos/Vatsa10/Harbour/commits/ad11861c37b9e5b42e91ad770c256977b6395611"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/123623531?v=4","ev